    function formatedSpanReplace(context) {
        function replaceSpan(text) {
            const pattern = /\[\[(.*?)\]\]/g;
            return text
                .replace(/\[\[\/\]\]/g, '</span>')
                .replace(pattern, (match, styles) => {
                    return `<span style="${styles}">`;
                });
        }
        for (const [key, value] of Object.entries(context.formatedPayload)) {
            if (typeof value == 'string' && key.toLowerCase().indexOf("url") < 0)
                context.formatedPayload[key] = replaceSpan(value)
        }
    }

    function setSendStat(context) {
        Evergage.cashDom(`[data-evg-campaign-id="${context.campaign}"][data-evg-experience-id="${context.experience}"]`).on("click", () => {
            Evergage.sendStat({
                campaignStats: [{
                    experienceId: context.experience,
                    stat: 'Clickthrough',
                    control: context.userGroup == "Control"
                }]
            })
        })
    }

    function apply(context, template) {
        const contentZoneSelector = Evergage.getContentZoneSelector(context.contentZone);
        return Evergage.DisplayUtils
            .pageElementLoaded(contentZoneSelector)
            .then((element) => {
                formatedSpanReplace(context);
                const html = template(context);
                Evergage.cashDom(element).after(html);
                Evergage.cashDom(element).remove();
                setSendStat(context);
            });
    }

    function reset(context, template) {
        Evergage.cashDom("#evg-new-template").remove();
    }

    function control(context) {
        const contentZoneSelector = Evergage.getContentZoneSelector(context.contentZone);
        return Evergage.DisplayUtils
            .pageElementLoaded(contentZoneSelector)
            .then((element) => {
                Evergage.cashDom(element).attr({
                    "data-evg-campaign-id": context.campaign,
                    "data-evg-experience-id": context.experience,
                    "data-evg-user-group": context.userGroup
                });
            });
    }

    registerTemplate({
        apply: apply,
        reset: reset,
        control: control
    });

